-- A deferred parent FK permits arbitrary snapshot order. During BEFORE INSERT
-- the new ID is not yet a row, so also check ancestor parent IDs for a cycle.
create or replace function public.orbit_reject_branch_cycle() returns trigger language plpgsql security invoker
set search_path = '' as $$
begin
  if new.parent_id is null then return new; end if;
  if new.parent_id=new.id then raise exception 'Branch cannot be its own parent'; end if;
  if exists(
    with recursive ancestor_chain as (
      select b.id,b.parent_id,array[b.id] as visited from public.branches b
        where b.owner_id=new.owner_id and b.id=new.parent_id
      union all
      select b.id,b.parent_id,a.visited||b.id from public.branches b
        join ancestor_chain a on a.parent_id=b.id
        where b.owner_id=new.owner_id and not b.id=any(a.visited)
    ) select 1 from ancestor_chain where id=new.id or parent_id=new.id
  ) then raise exception 'A branch cannot move inside its descendants'; end if;
  return new;
end;
$$;
revoke all on function public.orbit_reject_branch_cycle() from public,anon;
grant execute on function public.orbit_reject_branch_cycle() to authenticated;

-- Restrictive policies AND the immutable original ownership policies apply.
-- Thus neither a stranger's own rows nor forged owner IDs are accessible.
do $$
declare table_name text;
begin
  foreach table_name in array array['profiles','branches','tasks','journal_entries','milestones','widget_layouts','preferences'] loop
    execute format('create policy orbit_single_owner on public.%I as restrictive for all to authenticated using ((select private.is_orbit_owner())) with check ((select private.is_orbit_owner()))',table_name);
  end loop;
end;
$$;

create table private.workspace_revisions (
  owner_id uuid primary key references auth.users(id) on delete cascade,
  revision bigint not null default 0 check(revision>=0)
);
alter table private.workspace_revisions enable row level security;
revoke all on private.workspace_revisions from public,anon,authenticated;
grant select,insert,update on private.workspace_revisions to authenticated;
create policy workspace_revision_owner on private.workspace_revisions for all to authenticated
 using(owner_id=(select auth.uid()) and (select private.is_orbit_owner()))
 with check(owner_id=(select auth.uid()) and (select private.is_orbit_owner()));

-- Acquire the revision lock BEFORE data rows for both direct DML and RPCs.
-- This avoids opposite lock ordering between direct updates and snapshot saves.
create function private.lock_workspace_revision() returns trigger language plpgsql security invoker
set search_path = '' as $$
begin
  if auth.uid() is not null and private.is_orbit_owner() then
    insert into private.workspace_revisions(owner_id) values(auth.uid()) on conflict do nothing;
    perform revision from private.workspace_revisions where owner_id=auth.uid() for update;
  end if;
  return null;
end;
$$;
revoke all on function private.lock_workspace_revision() from public,anon;
grant execute on function private.lock_workspace_revision() to authenticated;

-- A revision changes for direct owner DML too, so an RPC cannot silently
-- overwrite a valid concurrent direct update. RPCs lock this same row first.
create function private.bump_workspace_revision() returns trigger language plpgsql security invoker
set search_path = '' as $$
begin
  if auth.uid() is not null and private.is_orbit_owner() then
    insert into private.workspace_revisions(owner_id,revision) values(auth.uid(),1)
    on conflict(owner_id) do update set revision=private.workspace_revisions.revision+1;
  end if;
  return null;
end;
$$;
revoke all on function private.bump_workspace_revision() from public,anon;
grant execute on function private.bump_workspace_revision() to authenticated;
do $$
declare table_name text;
begin
  foreach table_name in array array['profiles','branches','tasks','journal_entries','milestones','widget_layouts','preferences'] loop
    execute format('create trigger orbit_revision_lock before insert or update or delete on public.%I for each statement execute function private.lock_workspace_revision()',table_name);
    execute format('create trigger orbit_revision after insert or update or delete on public.%I for each statement execute function private.bump_workspace_revision()',table_name);
  end loop;
end;
$$;

-- A separate projection contains only owner-confirmed publishable plain text.
-- Private source identifiers live in an unexposed mapping table, never in this
-- table, a public view, an RPC result or an anonymous join relationship.
create table public.published_content (
  id uuid primary key default gen_random_uuid(),
  kind text not null check(kind in ('task','journal','branch','milestone')),
  title text not null check(char_length(title) between 1 and 180 and title !~ '[<>]'),
  excerpt text not null default '' check(char_length(excerpt)<=2000 and excerpt !~ '[<>]'),
  published_date date,
  updated_at timestamptz not null default now()
);
alter table public.published_content enable row level security;
revoke all on public.published_content from public,anon,authenticated;
grant select on public.published_content to anon,authenticated;
grant insert,update,delete on public.published_content to authenticated;
create policy publication_owner on public.published_content for all to authenticated
 using((select private.is_orbit_owner())) with check((select private.is_orbit_owner()));
create policy publication_public_read on public.published_content for select to anon,authenticated
 using((select private.public_reads_enabled()));
create index published_content_date_idx on public.published_content(published_date desc);

create table private.publication_sources (
  publication_id uuid primary key references public.published_content(id) on delete cascade,
  kind text not null check(kind in ('task','journal','branch','milestone')),
  source_id text not null,
  unique(kind,source_id)
);
alter table private.publication_sources enable row level security;
revoke all on private.publication_sources from public,anon,authenticated;
grant select,insert,update,delete on private.publication_sources to authenticated;
create policy publication_source_owner on private.publication_sources for all to authenticated
 using((select private.is_orbit_owner())) with check((select private.is_orbit_owner()));

-- Deferred deletion checks the FINAL source state, so full-snapshot replacement
-- keeps approved projections, while any committed source deletion unpublishes.
create function private.unpublish_deleted_source() returns trigger language plpgsql security invoker
set search_path = '' as $$
declare source_exists boolean; source_kind text;
begin
  source_kind=case tg_table_name when 'tasks' then 'task' when 'branches' then 'branch'
    when 'journal_entries' then 'journal' else 'milestone' end;
  execute format('select exists(select 1 from public.%I where owner_id=$1 and id=$2)',tg_table_name)
    into source_exists using old.owner_id,old.id;
  if not source_exists then
    delete from public.published_content where id in(select publication_id from private.publication_sources
      where kind=source_kind and source_id=old.id);
  end if;
  return null;
end;
$$;
revoke all on function private.unpublish_deleted_source() from public,anon;
grant execute on function private.unpublish_deleted_source() to authenticated;
do $$
declare table_name text;
begin
  foreach table_name in array array['branches','tasks','journal_entries','milestones'] loop
    execute format('create constraint trigger orbit_source_unpublish after delete on public.%I deferrable initially deferred for each row execute function private.unpublish_deleted_source()',table_name);
  end loop;
end;
$$;

create function public.load_owner_snapshot() returns jsonb language plpgsql security invoker
set search_path = '' as $$
declare owner_uuid uuid:=auth.uid(); result jsonb;
begin
  if not private.is_orbit_owner() then raise exception using errcode='42501',message='Owner access required'; end if;
  -- One SQL statement uses one MVCC snapshot for revision and all projections.
  select jsonb_build_object('revision',coalesce((select revision from private.workspace_revisions where owner_id=owner_uuid),0),
    'snapshot',jsonb_build_object(
      'branches',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',id,'parentId',coalesce(parent_id,'root'),'label',label,'color',color)) order by created_at,id) from public.branches where owner_id=owner_uuid),'[]'),
      'tasks',coalesce((select jsonb_agg(jsonb_build_object('id',id,'projectId',project_id,'title',title,'dueDate',coalesce(due_date::text,''),'urgency',urgency,'effortMinutes',effort_minutes,'status',status,'criteria',criteria,'description',description,'resourceUrl',coalesce(resource_url,''),'createdAt',created_at,'completedAt',coalesce(completed_at::text,'')) order by created_at,id) from public.tasks where owner_id=owner_uuid),'[]'),
      'journalEntries',coalesce((select jsonb_agg(jsonb_build_object('id',id,'date',entry_date,'title',title,'html',body_html,'createdAt',created_at,'updatedAt',updated_at) order by created_at,id) from public.journal_entries where owner_id=owner_uuid),'[]'),
      'milestones',coalesce((select jsonb_agg(jsonb_build_object('id',id,'date',marker_date,'title',title) order by created_at,id) from public.milestones where owner_id=owner_uuid),'[]'),
      'spatialLayout',coalesce((select jsonb_object_agg(widget_key,jsonb_strip_nulls(jsonb_build_object('x',x,'y',y,'width',width,'height',height))) from public.widget_layouts where owner_id=owner_uuid),'{}'),
      'preferences',coalesce((select jsonb_build_object('colorMode',color_mode,'timezone',timezone) from public.preferences where owner_id=owner_uuid),'{"colorMode":"deadline","timezone":"Asia/Jakarta"}'),
      'profile',coalesce((select jsonb_build_object('displayName',display_name) from public.profiles where user_id=owner_uuid),'{"displayName":"My space"}')
    )) into result;
  return result;
end;
$$;
revoke all on function public.load_owner_snapshot() from public,anon;
grant execute on function public.load_owner_snapshot() to authenticated;

create function public.save_owner_snapshot(p_snapshot jsonb,p_expected_revision bigint) returns jsonb language plpgsql security invoker
set search_path = '' as $$
declare owner_uuid uuid:=auth.uid(); current_revision bigint; key_name text; item jsonb; publication uuid;
begin
  if not private.is_orbit_owner() then raise exception using errcode='42501',message='Owner access required'; end if;
  if p_expected_revision is null or p_expected_revision<0 or jsonb_typeof(p_snapshot) is distinct from 'object' then
    raise exception using errcode='22023',message='Invalid snapshot';
  end if;
  foreach key_name in array array['branches','tasks','journalEntries','milestones'] loop
    if jsonb_typeof(p_snapshot->key_name) is distinct from 'array' then raise exception using errcode='22023',message='Invalid snapshot collection'; end if;
  end loop;
  if jsonb_array_length(p_snapshot->'tasks')>10000 or jsonb_array_length(p_snapshot->'branches')>4000 or jsonb_array_length(p_snapshot->'journalEntries')>600 or jsonb_array_length(p_snapshot->'milestones')>500
    or jsonb_typeof(p_snapshot->'spatialLayout') is distinct from 'object' or jsonb_typeof(p_snapshot->'preferences') is distinct from 'object' then
    raise exception using errcode='22023',message='Invalid snapshot limits';
  end if;
  insert into private.workspace_revisions(owner_id) values(owner_uuid) on conflict do nothing;
  select revision into current_revision from private.workspace_revisions where owner_id=owner_uuid for update;
  if current_revision<>p_expected_revision then raise exception using errcode='40001',message='Snapshot conflict'; end if;
  -- Every statement is one transaction; constraint/error failure rolls all back.
  -- Defer composite FKs for arbitrary branch order and replacement semantics.
  set constraints public.branches_parent_fkey,public.tasks_branch_fkey deferred;
  delete from public.tasks where owner_id=owner_uuid;
  delete from public.branches where owner_id=owner_uuid;
  delete from public.journal_entries where owner_id=owner_uuid;
  delete from public.milestones where owner_id=owner_uuid;
  delete from public.widget_layouts where owner_id=owner_uuid;
  for item in select value from jsonb_array_elements(p_snapshot->'branches') loop
    insert into public.branches(owner_id,id,parent_id,label,color) values(owner_uuid,item->>'id',nullif(item->>'parentId','root'),item->>'label',nullif(item->>'color',''));
  end loop;
  for item in select value from jsonb_array_elements(p_snapshot->'tasks') loop
    insert into public.tasks(owner_id,id,project_id,title,due_date,urgency,effort_minutes,status,criteria,description,resource_url,created_at,completed_at)
    values(owner_uuid,item->>'id',item->>'projectId',item->>'title',nullif(item->>'dueDate','')::date,coalesce((item->>'urgency')::smallint,1),coalesce((item->>'effortMinutes')::integer,0),coalesce(item->>'status','captured'),coalesce(item->>'criteria',''),coalesce(item->>'description',''),nullif(item->>'resourceUrl',''),coalesce(nullif(item->>'createdAt','')::timestamptz,now()),nullif(item->>'completedAt','')::timestamptz);
  end loop;
  for item in select value from jsonb_array_elements(p_snapshot->'journalEntries') loop
    insert into public.journal_entries(owner_id,id,entry_date,title,body_html,created_at,updated_at)
    values(owner_uuid,item->>'id',(item->>'date')::date,coalesce(item->>'title',''),coalesce(item->>'html',''),coalesce(nullif(item->>'createdAt','')::timestamptz,now()),coalesce(nullif(item->>'updatedAt','')::timestamptz,now()));
  end loop;
  for item in select value from jsonb_array_elements(p_snapshot->'milestones') loop
    insert into public.milestones(owner_id,id,title,marker_date) values(owner_uuid,item->>'id',item->>'title',(item->>'date')::date);
  end loop;
  for key_name,item in select key,value from jsonb_each(p_snapshot->'spatialLayout') loop
    insert into public.widget_layouts(owner_id,widget_key,x,y,width,height) values(owner_uuid,key_name,(item->>'x')::numeric,(item->>'y')::numeric,(item->>'width')::integer,(item->>'height')::integer);
  end loop;
  insert into public.preferences(owner_id,color_mode,timezone) values(owner_uuid,coalesce(p_snapshot->'preferences'->>'colorMode','deadline'),coalesce(p_snapshot->'preferences'->>'timezone','Asia/Jakarta'))
    on conflict(owner_id) do update set color_mode=excluded.color_mode,timezone=excluded.timezone;
  insert into public.profiles(user_id,display_name) values(owner_uuid,coalesce(p_snapshot->'profile'->>'displayName','My space'))
    on conflict(user_id) do update set display_name=excluded.display_name;
  -- Remove only deleted sources; existing publication text is an independent
  -- approved snapshot, never automatically republished from private edits.
  for publication in select s.publication_id from private.publication_sources s where
    (s.kind='task' and not exists(select 1 from public.tasks where owner_id=owner_uuid and id=s.source_id)) or
    (s.kind='branch' and not exists(select 1 from public.branches where owner_id=owner_uuid and id=s.source_id)) or
    (s.kind='journal' and not exists(select 1 from public.journal_entries where owner_id=owner_uuid and id=s.source_id)) or
    (s.kind='milestone' and not exists(select 1 from public.milestones where owner_id=owner_uuid and id=s.source_id))
  loop delete from public.published_content where id=publication; end loop;
  -- Check deferred relations inside the RPC so errors occur before returning.
  set constraints public.branches_parent_fkey,public.tasks_branch_fkey immediate;
  return jsonb_build_object('revision',(select revision from private.workspace_revisions where owner_id=owner_uuid));
end;
$$;
revoke all on function public.save_owner_snapshot(jsonb,bigint) from public,anon;
grant execute on function public.save_owner_snapshot(jsonb,bigint) to authenticated;

create function public.publish_content(p_kind text,p_source_id text,p_expected_title text,p_excerpt text default '',p_publication_date date default null)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare owner_uuid uuid:=auth.uid(); source_title text; publication uuid; result jsonb;
begin
  if not private.is_orbit_owner() then raise exception using errcode='42501',message='Owner access required'; end if;
  -- Serialize publication with source writes/deletion; the independent safe
  -- projection must never outlive a concurrent committed source deletion.
  insert into private.workspace_revisions(owner_id) values(owner_uuid) on conflict do nothing;
  perform revision from private.workspace_revisions where owner_id=owner_uuid for update;
  if p_kind='task' then select title into source_title from public.tasks where owner_id=owner_uuid and id=p_source_id;
  elsif p_kind='branch' then select label into source_title from public.branches where owner_id=owner_uuid and id=p_source_id;
  elsif p_kind='journal' then select coalesce(nullif(title,''),'Untitled') into source_title from public.journal_entries where owner_id=owner_uuid and id=p_source_id;
  elsif p_kind='milestone' then select title into source_title from public.milestones where owner_id=owner_uuid and id=p_source_id;
  else raise exception using errcode='22023',message='Invalid publication kind'; end if;
  if source_title is null then raise exception using errcode='22023',message='Publication source not found'; end if;
  if source_title is distinct from p_expected_title then
    raise exception using errcode='40001',message='Publication title changed; review it again';
  end if;
  if p_excerpt is null or p_excerpt ~ '[<>]' or char_length(p_excerpt)>2000 or source_title ~ '[<>]' then
    raise exception using errcode='22023',message='Publication must be plain text';
  end if;
  select publication_id into publication from private.publication_sources where kind=p_kind and source_id=p_source_id for update;
  if publication is null then
    insert into public.published_content(kind,title,excerpt,published_date) values(p_kind,source_title,p_excerpt,p_publication_date) returning id into publication;
    insert into private.publication_sources(publication_id,kind,source_id) values(publication,p_kind,p_source_id);
  else
    update public.published_content set title=source_title,excerpt=p_excerpt,published_date=p_publication_date,updated_at=now() where id=publication;
  end if;
  select to_jsonb(p) into result from public.published_content p where id=publication;
  return result;
end;
$$;
create function public.unpublish_content(p_kind text,p_source_id text) returns void language plpgsql security invoker
set search_path = '' as $$
begin
  if not private.is_orbit_owner() then raise exception using errcode='42501',message='Owner access required'; end if;
  insert into private.workspace_revisions(owner_id) values(auth.uid()) on conflict do nothing;
  perform revision from private.workspace_revisions where owner_id=auth.uid() for update;
  delete from public.published_content where id in(select publication_id from private.publication_sources where kind=p_kind and source_id=p_source_id);
end;
$$;
revoke all on function public.publish_content(text,text,text,text,date),public.unpublish_content(text,text) from public,anon;
grant execute on function public.publish_content(text,text,text,text,date),public.unpublish_content(text,text) to authenticated;
